import json,re
a=json.load(open('exegenius/tasks/0003-argument.answer.json'))['root']
md=open('exegenius/tasks/0003-argument.md').read()
pages=re.findall(r'^- `([a-z0-9-]+)`: ',md.split('## Pages, in reading order')[1].split('## Concepts')[0],re.M)
known=re.findall(r'^- `([a-z0-9-]+)`: ',md.split('## Concepts the reader knows')[1].split('## Sources')[0],re.M)
idx={p:i for i,p in enumerate(pages)}
used=[];froms=set();bad=[]
def claims(n):
    out=[n['claim']]
    for c in n.get('children',[]): out+=claims(c)
    return out
def walk(n,anc):
    pg=n.get('page') or anc
    if n.get('page'): used.append(n['page'])
    for f in n.get('from',[]):
        froms.add(f)
        if f in idx:
            if idx[f]>=idx[pg]: bad.append((n['id'],f,pg))
        elif f not in known: bad.append((n['id'],'unknown',f))
    for ad in n.get('adds',[]):
        txt=' '.join(' '.join(re.findall(r'\$(.*?)\$',c)) for c in claims(n)[1:])
        if ad['symbol'] not in txt: bad.append((n['id'],'sym',ad['symbol']))
    for c in n.get('children',[]): walk(c,pg)
walk(a,None)
print(bad)
print([p for p in used if used.count(p)>1])
print([p for p in pages if p not in used and p not in froms])
EOF
